  hour: number;
  minute: number;
}

export function nextRun(schedule: Schedule): Date {
  const now = new Date();
  const next = new Date(now);

  next.setHours(schedule.hour, schedule.minute, 0, 0);

  if (next <= now) {
    next.setDate(next.getDate() + 1);
  }

  return next;
}

